pragma solidity ^0.8.20;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface ISwapRouter {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params) external payable returns (uint256 amountOut);
}

contract DCA {
    address public owner;
    ISwapRouter public router;
    address public tokenIn;
    address public tokenOut;
    uint24 public fee;

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(address _router, address _tokenIn, address _tokenOut, uint24 _fee) {
        owner = msg.sender;
        router = ISwapRouter(_router);
        tokenIn = _tokenIn;
        tokenOut = _tokenOut;
        fee = _fee;
    }

    function deposit(uint256 amount) external {
        require(IERC20(tokenIn).transferFrom(msg.sender, address(this), amount), "transferFrom failed");
    }

    function buy(uint256 amountIn, uint256 minOut) external onlyOwner {
        require(IERC20(tokenIn).approve(address(router), amountIn), "approve failed");

        ISwapRouter.ExactInputSingleParams memory params = ISwapRouter.ExactInputSingleParams({
            tokenIn: tokenIn,
            tokenOut: tokenOut,
            fee: fee,
            recipient: address(this),
            amountIn: amountIn,
            amountOutMinimum: minOut,
            sqrtPriceLimitX96: 0
        });

        router.exactInputSingle(params);
    }

    function withdraw(address token, uint256 amount) external onlyOwner {
        require(IERC20(token).transfer(owner, amount), "transfer failed");
    }
}
